    private function can(string $a):bool{return auth()->user()?->can("heavy-equipment.{$a}")||auth()->user()?->hasAnyRole(['super_admin','manajer_pimpro','user_area_gudang']);}private function authorizeModule(string $a):void{abort_unless($this->can($a),403);}
